package com.quicknotes.app;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import org.json.*;
/** Opt-in ongoing location monitoring, with an explicit persistent notification. */
public class LocationService extends Service implements LocationListener {
 LocationManager manager;static volatile LocationService current;
 public IBinder onBind(Intent i){return null;}
 static boolean permitted(Context c){return c.checkSelfPermission("android.permission.ACCESS_FINE_LOCATION")==PackageManager.PERMISSION_GRANTED||c.checkSelfPermission("android.permission.ACCESS_COARSE_LOCATION")==PackageManager.PERMISSION_GRANTED;}
 static boolean any(JSONObject d)throws Exception{JSONArray a=d.getJSONArray("items");for(int n=0;n<a.length();n++){JSONObject i=a.getJSONObject(n);if(!i.optBoolean("done")&&!i.optBoolean("deleted")&&i.optJSONObject("location")!=null&&Reminders.activeList(d,i.optString("list")))return true;}return false;}
 static void refresh(Context c,JSONObject d)throws Exception{if(!any(d)){c.stopService(new Intent(c,LocationService.class));return;}if(!permitted(c))return;if(current!=null)return;try{c.startForegroundService(new Intent(c,LocationService.class));}catch(Exception e){android.util.Log.w("QuickNotes","Open the app to resume location reminders",e);}}
 public void onCreate(){super.onCreate();current=this;NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("location-reminders","Location reminder monitoring",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);startForeground(7002,new Notification.Builder(this,"location-reminders").setSmallIcon(R.drawable.ic_notification).setContentTitle("Location reminders enabled").setContentText("Watching for your arrival or departure").setContentIntent(open).setOngoing(true).build());manager=(LocationManager)getSystemService(LOCATION_SERVICE);try{if(!permitted(this)){stopSelf();return;}for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})if(manager.isProviderEnabled(provider))manager.requestLocationUpdates(provider,30000,25,this);}catch(Exception e){stopSelf();}}
 public int onStartCommand(Intent i,int flags,int start){return START_STICKY;}
 public void onLocationChanged(Location location){new Thread(()->{try{synchronized(MainActivity.STORE_LOCK){evaluate(this,Reminders.read(this),location);}}catch(Exception e){android.util.Log.w("QuickNotes","Location check failed",e);}},"quicknotes-location").start();}
 static boolean crossed(Boolean previous,boolean inside,String mode){return "leave".equals(mode)?Boolean.TRUE.equals(previous)&&!inside:inside&&!Boolean.TRUE.equals(previous);}
 static void evaluate(Context c,JSONObject d,Location location)throws Exception{JSONArray a=d.getJSONArray("items");SharedPreferences prefs=c.getSharedPreferences("locations",0);for(int n=0;n<a.length();n++){JSONObject i=a.getJSONObject(n),l=i.optJSONObject("location");if(l==null||i.optBoolean("done")||i.optBoolean("deleted")||!Reminders.activeList(d,i.optString("list")))continue;double radius=Math.max(100.584,Math.min(241401.6,l.optDouble("radius",100.584)));if(location.hasAccuracy()&&location.getAccuracy()>radius)continue;float[] result=new float[1];Location.distanceBetween(location.getLatitude(),location.getLongitude(),l.getDouble("lat"),l.getDouble("lng"),result);String key=i.getString("id")+":"+l.toString().hashCode();Boolean previous=prefs.contains(key)?prefs.getBoolean(key,false):null;boolean inside=result[0]<=radius;if(previous!=null&&Math.abs(result[0]-radius)<Math.min(30,radius*.1))inside=previous;boolean fire=crossed(previous,inside,l.optString("mode","arrive"));prefs.edit().putBoolean(key,inside).apply();if(fire)Reminders.notifyReminder(c,i);}}
 public void onStatusChanged(String p,int status,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}
 public void onDestroy(){if(manager!=null)manager.removeUpdates(this);current=null;super.onDestroy();}
}
